import{_ as o,o as t,c as r,a5 as e}from"./chunks/framework.BjM_ivYE.js";const c=JSON.parse('{"title":"로봇 한쪽 쏠림","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"ko/manual/troubleshooting/robot-drifts.md","filePath":"ko/manual/troubleshooting/robot-drifts.md","lastUpdated":1788840704000}'),n={name:"ko/manual/troubleshooting/robot-drifts.md"};function s(l,a,i,p,d,h){return t(),r("div",null,[...a[0]||(a[0]=[e('<h1 id="로봇-한쪽-쏠림" tabindex="-1">로봇 한쪽 쏠림 <a class="header-anchor" href="#로봇-한쪽-쏠림" aria-label="Permalink to &quot;로봇 한쪽 쏠림&quot;">​</a></h1><p>똑바로 가라고 했는데 로봇이 한쪽으로 밀리거나, 서 있을 때 몸이 한쪽으로 기울어 보이는 경우입니다. 원인이 하나가 아니므로 <strong>아래 순서대로</strong> 확인하세요. 앞쪽 항목일수록 흔하고 확인이 쉽습니다.</p><h2 id="floor-and-pose" tabindex="-1">1. 바닥과 초기 자세 <a class="header-anchor" href="#floor-and-pose" aria-label="Permalink to &quot;1. 바닥과 초기 자세 {#floor-and-pose}&quot;">​</a></h2><p><strong>원인:</strong> 기울어진 바닥이나 미끄러운 바닥에서는 로봇이 한쪽으로 밀립니다. 초기 자세가 좌우 대칭이 아닌 상태로 시작해도 마찬가지입니다.</p><p><strong>해결:</strong> 평평하고 단단한 바닥에서 다시 시도합니다. 전원을 켜기 전 다리가 좌우 대칭으로 접혀 있는지 확인하세요.</p><p><strong>→ <a href="/RBQ/ko/manual/operation/initial-pose.html">초기 자세</a></strong></p><h2 id="payload" tabindex="-1">2. 페이로드 설정 <a class="header-anchor" href="#payload" aria-label="Permalink to &quot;2. 페이로드 설정 {#payload}&quot;">​</a></h2><p><strong>원인:</strong> 로봇에 장비를 얹었는데 그 무게와 위치를 입력하지 않았거나 실제와 다르게 입력하면, 로봇은 무게중심을 잘못 계산해 한쪽으로 치우칩니다. 장비를 떼어냈는데 값이 남아 있어도 같은 문제가 생깁니다.</p><p><strong>해결:</strong> 현재 장착 상태와 입력값이 일치하는지 확인하고, 다르면 다시 설정합니다. 장비를 모두 떼어냈다면 값을 초기화합니다.</p><p><strong>→ <a href="/RBQ/ko/manual/troubleshooting/payload_setting.html">Payload 설정</a></strong></p><h2 id="zmp" tabindex="-1">3. ZMP 캘리브레이션 <a class="header-anchor" href="#zmp" aria-label="Permalink to &quot;3. ZMP 캘리브레이션 {#zmp}&quot;">​</a></h2><p><strong>원인:</strong> 로봇이 서 있을 때 지면 반력의 중심이 틀어져 있으면 보행 중에도 계속 한쪽으로 쏠립니다. 치우침 증상에 가장 직접적으로 작용하는 항목입니다.</p><p><strong>해결:</strong> ZMP 캘리브레이션을 다시 실행합니다. 평평하고 단단한 바닥에서, 로봇에 아무것도 얹지 않은 상태로 진행하세요.</p><p><strong>→ <a href="/RBQ/ko/manual/troubleshooting/calibration-tuning.html">캘리브레이션 &amp; 튜닝</a></strong></p><div class="sb sb-caution"><div class="sb-icon"><span class="sb-warn" aria-hidden="true">⚠</span></div><div class="sb-content"><p class="custom-block-title">주의</p><p>캘리브레이션 중에는 로봇을 밀거나 로봇 위에 물건을 올리지 마세요. 그 상태로 보정되면 치우침이 오히려 심해집니다.</p></div></div><h2 id="leg-module" tabindex="-1">4. 다리 모듈 상태 <a class="header-anchor" href="#leg-module" aria-label="Permalink to &quot;4. 다리 모듈 상태 {#leg-module}&quot;">​</a></h2><p><strong>원인:</strong> 다리 모듈이나 발이 기구적으로 헐거워졌거나 마모되면 그쪽으로 밀립니다.</p><p><strong>해결:</strong> 로봇을 앉히고 전원을 끈 뒤, 다리를 손으로 흔들어 유격이 있는지, 발 패드가 한쪽만 심하게 닳지 않았는지 확인합니다.</p><p><strong>→ <a href="/RBQ/ko/manual/maintenance/leg-module.html">다리 모듈</a> · <a href="/RBQ/ko/manual/maintenance/foot.html">발</a></strong></p><h2 id="still-stuck" tabindex="-1">그래도 해결되지 않으면 <a class="header-anchor" href="#still-stuck" aria-label="Permalink to &quot;그래도 해결되지 않으면 {#still-stuck}&quot;">​</a></h2><p>위 1~4번 중 어디까지 확인했는지, 그리고 아래 내용을 함께 알려주시면 확인이 빠릅니다.</p><ul><li>어느 방향으로 치우치는지 (좌 · 우 · 앞 · 뒤)</li><li>서 있을 때부터 기울어 있는지, 걸을 때만 밀리는지</li><li>특정 보행 모드에서만 발생하는지</li></ul><p><strong>→ <a href="/RBQ/ko/manual/support/">기술지원 요청</a></strong></p>',23)])])}const g=o(n,[["render",s]]);export{c as __pageData,g as default};
